import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        final int Z = 100;
        final int N = Z * Z;
        List<Integer> px = new ArrayList<>(Collections.nCopies(N, 0));
        List<Integer> py = new ArrayList<>(Collections.nCopies(N, 0));
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < N; i++) {
            adj.add(new ArrayList<>());
        }
        List<Integer> capacity = new ArrayList<>(Collections.nCopies(2 * N, 0));
        List<Integer> cost = new ArrayList<>(Collections.nCopies(2 * N, 0));
        List<int[]> edges = new ArrayList<>();
        int s = 0;
        int t = n * 100 + 1;

        // Helper method to add edges
        class Graph {
            void addEdge(int u, int v, int cap, int cst) {
                edges.add(new int[]{u, v});
                capacity.add(cap);
                cost.add(cst);
                adj.get(u).add(edges.size() - 1);
                edges.add(new int[]{v, u});
                capacity.add(0);
                cost.add(-cst);
                adj.get(v).add(edges.size() - 1);
            }
        }
        Graph graph = new Graph();

        for (int i = 1; i <= 100; ++i)
            graph.addEdge(i, t, 100, 0);
        for (int i = 1, v; i <= k; ++i) {
            v = Integer.parseInt(br.readLine());
            graph.addEdge(s, (v - 1) * 100 + 1, 1, 0);
        }
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j < 100; ++j) {
                graph.addEdge((i - 1) * 100 + j, (i - 1) * 100 + j + 1, 100, c);
            }
        }
        for (int i = 1, u, v; i <= m; ++i) {
            st = new StringTokenizer(br.readLine());
            u = Integer.parseInt(st.nextToken());
            v = Integer.parseInt(st.nextToken());
            for (int j = 1; j < 100; ++j) {
                int idx = (u - 1) * 100 + j;
                int idy = (v - 1) * 100 + j + 1;
                for (int k = 1; k <= 50; ++k) {
                    int costVal = c + (k * k - (k - 1) * (k - 1)) * d;
                    graph.addEdge(idx, idy, 1, costVal);
                }
            }
            for (int j = 1; j < 100; ++j) {
                int idx = (v - 1) * 100 + j;
                int idy = (u - 1) * 100 + j + 1;
                for (int k = 1; k <= 50; ++k) {
                    int costVal = c + (k * k - (k - 1) * (k - 1)) * d;
                    graph.addEdge(idx, idy, 1, costVal);
                }
            }
        }

        int totalFlow = 0, totalCost = 0;
        int[] dist = new int[N + 2];
        int[] parent = new int[N + 2];
        int[] parentEdge = new int[N + 2];

        while (true) {
            Arrays.fill(dist, Integer.MAX_VALUE);
            dist[s] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int i : adj.get(u)) {
                    int v = edges.get(i)[1];
                    if (capacity.get(i) > 0 && dist[v] > dist[u] + cost.get(i)) {
                        dist[v] = dist[u] + cost.get(i);
                        parent[v] = u;
                        parentEdge[v] = i;
                        q.offer(v);
                    }
                }
            }
            if (dist[t] == Integer.MAX_VALUE) break;
            int f = Integer.MAX_VALUE;
            for (int u = t; u != s; u = parent[u]) {
                f = Math.min(f, capacity.get(parentEdge[u]));
            }
            for (int u = t; u != s; u = parent[u]) {
                int edgeIdx = parentEdge[u];
                capacity.set(edgeIdx, capacity.get(edgeIdx) - f);
                int revIdx = edges.get(edgeIdx)[1];
                // Find reverse edge index
                for (int rev : adj.get(edges.get(edgeIdx)[1])) {
                    if (edges.get(rev)[1] == u) {
                        capacity.set(rev, capacity.get(rev) + f);
                        break;
                    }
                }
            }
            totalCost += dist[t] * f;
            totalFlow += f;
        }
        System.out.println(totalCost);
    }
